/** Windowed native lists retain complete navigation, role caches, responsive rows and automatic paging. */
async page => {
  const assert = (value, message) => { if (!value) throw new Error(message) }, errors = [], onError = error => errors.push(error.message)
  const media = route => route.fulfill({ status: 200, contentType: 'image/svg+xml', body: '<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="800"><rect width="1200" height="800" fill="#496252"/></svg>' })
  page.on('pageerror', onError); await page.route('**/api/visual-curator/resource**', media)
  try {
    await page.setViewportSize({ width: 1440, height: 1000 }); await page.reload({ waitUntil: 'domcontentloaded' }); await page.waitForFunction(() => window.remainingFixture)
    await page.evaluate(() => window.remainingFixture.show('dataset', 1024))
    await page.getByRole('tab', { name: '逐图观察', exact: true }).click()
    await page.waitForFunction(() => document.querySelectorAll('.vc-dataset-sample').length > 0)
    const sampleRows = await page.locator('.vc-dataset-sample').count()
    assert(sampleRows < 32, 'Loaded observations mount only the reading window')
    const samples = page.locator('.vc-dataset-detail-scroll')
    await samples.evaluate(element => { element.scrollTop = 2500 })
    await page.waitForFunction(() => [...document.querySelectorAll('.vc-dataset-sample')].some(row => row.getAttribute('data-reference-id') !== 'synthetic-ref-0'))
    const before = await samples.evaluate(element => element.scrollTop)
    for (let index = 0; index < 3; index++) {
      await page.getByRole('tab', { name: '概览', exact: true }).click()
      assert(await page.locator('.vc-dataset-sample').count() === 0, 'Inactive observation DOM must unmount')
      await page.getByRole('tab', { name: '逐图观察', exact: true }).click()
      await page.waitForFunction(expected => Math.abs(document.querySelector('.vc-dataset-detail-scroll').scrollTop - expected) < 2, before)
    }
    await samples.evaluate(element => { element.scrollTop = element.scrollHeight })
    await page.waitForFunction(() => !!document.querySelector('[data-reference-id="synthetic-ref-1023"]'))
    await page.locator('.vc-dataset-role-filter button').nth(2).click()
    await page.waitForFunction(() => document.querySelector('[data-sample-total]')?.getAttribute('data-sample-total') === '204')
    const afterRole = await page.evaluate(() => window.remainingFixture.reads().length)
    await page.locator('.vc-dataset-role-filter button').first().click()
    await page.waitForFunction(() => !!document.querySelector('[data-reference-id="synthetic-ref-1023"]'))
    assert(await page.evaluate(() => window.remainingFixture.reads().length) === afterRole, 'Returning to all roles must reuse loaded pages')
    await page.setViewportSize({ width: 390, height: 844 }); await samples.evaluate(element => { element.scrollTop = element.scrollHeight })
    await page.waitForFunction(() => !!document.querySelector('[data-reference-id="synthetic-ref-1023"]'))
    assert(await samples.evaluate(element => element.scrollWidth <= element.clientWidth + 1), 'Narrow observations must wrap without overflow')

    await page.setViewportSize({ width: 1440, height: 1000 }); await page.evaluate(() => window.remainingFixture.show('dataset', 45, true))
    await page.getByRole('tab', { name: '逐图观察', exact: true }).click()
    for (const total of [40, 45]) {
      await samples.evaluate(element => { element.scrollTop = element.scrollHeight })
      await page.waitForFunction(total => document.querySelector('[data-sample-total]')?.getAttribute('data-sample-total') === String(total), total)
    }
    const cursors = await page.evaluate(() => window.remainingFixture.reads().map(read => read.pageToken ?? null))
    assert(JSON.stringify(cursors) === JSON.stringify([null, '20', '40']), 'Bottom paging must read each cursor once and retain prior pages')
    await samples.evaluate(element => { element.scrollTop = element.scrollHeight })
    await page.waitForFunction(() => !!document.querySelector('[data-reference-id="synthetic-ref-44"]'))
    await page.getByRole('button', { name: '关闭', exact: true }).last().click()

    await page.evaluate(() => window.remainingFixture.show('batch', 20))
    await page.waitForFunction(() => document.querySelectorAll('.vc-search-batch figure').length === 20)
    const results = page.locator('.vc-search-batches-scroll')
    await results.evaluate(element => { element.scrollTop = element.scrollHeight })
    const appendOffset = await results.evaluate(element => element.scrollTop)
    await page.evaluate(() => window.remainingFixture.appendResults())
    await page.waitForFunction(() => document.querySelector('[data-result-total]')?.getAttribute('data-result-total') === '40' && document.querySelectorAll('.vc-search-batch figure').length > 1)
    await page.waitForFunction(expected => Math.abs(document.querySelector('.vc-search-batches-scroll').scrollTop - expected) < 2, appendOffset)
    await page.evaluate(() => window.remainingFixture.show('batch', 1024))
    await page.waitForFunction(() => document.querySelectorAll('.vc-search-batch figure').length > 1)
    const batchRows = await page.locator('.vc-search-batch figure').count()
    assert(batchRows < 128, 'Saved result cards must be windowed')
    await results.evaluate(element => { element.scrollTop = element.scrollHeight })
    await page.waitForFunction(() => [...document.querySelectorAll('.vc-search-batch img')].some(image => image.alt === 'Synthetic vehicle 0-1023'))
    await page.locator('.vc-search-batch figure').last().getByRole('button').first().click()
    const lightbox = page.getByRole('dialog')
    await lightbox.waitFor(); assert((await lightbox.innerText()).includes('1024 / 1024'), 'Lightbox navigation retains the full loaded sequence')
    await lightbox.getByRole('button', { name: '上一张', exact: true }).click()
    assert((await lightbox.innerText()).includes('1023 / 1024'), 'Previous image remains available after windowing')
    await lightbox.getByRole('button', { name: '关闭', exact: true }).click()
    await page.setViewportSize({ width: 390, height: 844 }); await results.evaluate(element => { element.scrollTop = element.scrollHeight })
    await page.waitForFunction(() => [...document.querySelectorAll('.vc-search-batch img')].some(image => image.alt === 'Synthetic vehicle 0-1023'))
    assert(await results.evaluate(element => element.scrollWidth <= element.clientWidth + 1), 'Narrow saved grids must not overflow')
    await page.setViewportSize({ width: 1440, height: 1000 }); await page.evaluate(() => window.remainingFixture.showBatches([329, 20, 45, 21]))
    await page.waitForFunction(() => document.querySelectorAll('[data-search-batch]').length === 4)
    await results.evaluate(element => { element.scrollTop = element.scrollHeight })
    await page.waitForFunction(() => [...document.querySelectorAll('.vc-search-batch img')].some(image => image.alt === 'Synthetic vehicle 3-20'))
    assert(errors.length === 0, `Native lists must not report page errors: ${errors.join('; ')}`)
    return { observationWindow: sampleRows < 32, observationTail: true, inactiveUnmount: true, scrollRestored: true, roleCache: true, automaticCursors: cursors, smallResultsEager: true, savedAppendPosition: true, savedResultWindow: batchRows < 128, savedResultTail: true, fullPreviewNavigation: true, narrowOverflow: false, laterBatchVisible: true, pageErrors: errors }
  } finally { page.off('pageerror', onError); await page.unroute('**/api/visual-curator/resource**', media) }
}
